export default function ({ body, previous }) {
  if (!Array.isArray(body)) throw Error("Invalid company page");
  return {
    state: {
      offset: (previous?.offset ?? 0) + body.length,
      companies: [...(previous?.companies ?? []), ...body],
    },
    more: body.length === 100,
  };
}

