export default function ({ companies, previous }) {
  const i = (previous?.i ?? -1) + 1,
    c = companies[i];
  if (c && (!c.id || !c.name || !c.website)) throw Error("Company needs id, name and website");
  return {
    state: { i },
    more: !!c,
    id: String(c?.id ?? ""),
    name: c?.name ?? "",
    website: c?.website ?? "",
  };
}

