export default async function ({ id, name, website, result }, ctx) {
  const key = "social-crawl:" + id,
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect unknown Supabase insert before retry");
  if (s?.status === "done") return { key, skip: true, row: {} };
  let social_media;
  try {
    social_media = JSON.parse(result).social_media;
  } catch {
    throw Error("Invalid model result");
  }
  if (!Array.isArray(social_media)) throw Error("Missing social_media");
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false, row: { company_name: name, company_website: website, social_media } };
}

